请以给定角色完成单条规则资格审查。
要求：
- 只能判断该规则是否适合进入下一阶段规划。
- `selection_reason` 直接写结论依据，不要泛泛而谈。
- `evidence` 必须引用 schema、原题摘要或规则声明中的具体证据。
- `score` 取 0 到 1，表示进入后续规划的把握度；拒绝时可以是 0 到 0.49。
- `risk_tags` 只保留高价值风险标签，例如 `low_novelty`、`shared_core_risk`、`semantic_mismatch`。
- 如果 schema 信息不足以判断，返回 `schema_insufficient`。
- 如果不确定，返回 `ineligible`。

{
  "review_type": "eligibility",
  "mode": "single_seed_extension",
  "review_role": "你扮演一名阈值优化审查官，重点判断可行性是否能自然升级为临界参数或极值阈值。",
  "rule_under_review": {
    "id": "feasibility_to_extremal_threshold",
    "family": "threshold_optimization",
    "audit_tags": [
      "single_seed",
      "threshold",
      "extremal_value"
    ],
    "handler": "feasibility_to_extremal_threshold",
    "enabled": true,
    "summary": "把判定或可行性问题扩展为求最小阈值、最大容量或临界参数的优化题。",
    "eligibility": {
      "required_seed_properties": [
        "原题可行性随某个参数具有清晰的单调性或分层结构",
        "阈值变化会改变主约束的可行区域"
      ],
      "forbidden_seed_properties": [
        "没有自然参数可优化",
        "阈值只是在原判定外层做机械二分"
      ]
    },
    "required_axis_changes": {
      "must_change": [
        "C",
        "O",
        "V"
      ]
    },
    "core_transformation": {
      "primary_operator": "feasibility_to_extremal_threshold",
      "target_shift": "从判断是否可行改成求临界阈值",
      "new_obligation": "定义阈值、可行区域和临界性证明"
    },
    "helpers": [
      {
        "id": "threshold_parameterization",
        "summary": "把原可行性条件参数化成可搜索的临界阈值。",
        "must_realize_in": [
          "core_constraints",
          "objective"
        ],
        "target_axes": [
          "C",
          "O"
        ],
        "innovation_role": "让目标从真假判断变成极值求解。",
        "difficulty_role": "要求算法处理阈值与可行性的耦合关系。",
        "prompt_guidance": [
          "阈值必须进入核心约束的定义。",
          "目标必须要求输出最小或最大临界参数。"
        ],
        "redlines": [
          "不能只是把 Yes/No 改成 0/1。",
          "不能让阈值脱离主约束。"
        ]
      },
      {
        "id": "monotone_boundary_invariant",
        "summary": "补出支撑临界值正确性的单调或边界不变量。",
        "must_realize_in": [
          "core_constraints",
          "invariant"
        ],
        "target_axes": [
          "C",
          "V"
        ],
        "innovation_role": "把可行性结构提升为边界定位问题。",
        "difficulty_role": "要求证明临界值两侧语义不同且可判定。",
        "prompt_guidance": [
          "说明阈值变化如何影响可行集合。",
          "不变量要支撑边界存在性或唯一性。"
        ],
        "redlines": [
          "不能只有经验性单调描述。",
          "不能省略边界正确性责任。"
        ]
      },
      {
        "id": "extremal_answer_contract",
        "summary": "把输出责任锁定为临界值及其可验证含义。",
        "must_realize_in": [
          "objective",
          "invariant"
        ],
        "target_axes": [
          "O",
          "V"
        ],
        "innovation_role": "让答案成为带证明语义的极值参数。",
        "difficulty_role": "要求解法同时证明达到与不可突破。",
        "prompt_guidance": [
          "目标应说明阈值为何是最小或最大。",
          "不变量应覆盖阈值的达成性和极限性。"
        ],
        "redlines": [
          "不能只输出任意可行参数。",
          "不能把极值证明留给备注。"
        ]
      }
    ],
    "validation_contract": {
      "hard_checks": [
        "阈值必须改变主求解目标",
        "阈值必须进入核心约束",
        "必须说明临界性不变量"
      ]
    },
    "examples": {
      "positive": "把判断是否存在合法方案改成求允许合法方案存在的最小容量。",
      "negative": "原题判定外面简单套一层二分但约束语义不变。"
    },
    "failure_templates": {
      "not_applicable": "这道种子题缺少自然临界参数，无法稳定扩成阈值优化题。",
      "difference_insufficient": "阈值目标没有改变主约束或证明义务，只是包装原判定。"
    },
    "planner_output_contract": {
      "required_fields": [
        "eligibility_reason",
        "core_transformation_summary",
        "difference_plan",
        "new_schema",
        "algorithmic_delta_claim",
        "anti_shallow_rationale",
        "applied_helpers"
      ]
    }
  },
  "schema_context": {
    "seed_schema": {
      "problem_id": "taco_codewars_24712bdb68a7",
      "source": "codewars",
      "input_structure": {
        "type": "string",
        "length": {
          "min": null,
          "max": null
        },
        "value_range": {
          "min": null,
          "max": null
        },
        "properties": {},
        "components": []
      },
      "core_constraints": {
        "constraints": [
          {
            "name": "operator_set",
            "description": "表达式中的运算符仅限于加号、减号和乘号,不会出现其他运算符。",
            "formal": "op ∈ {+, -, *}",
            "source_sections": [
              "description"
            ]
          },
          {
            "name": "unknown_digit_uniform_and_distinct",
            "description": "所有问号代表同一个十进制数字（0-9）,且该数字不能等于表达式中已经出现的任何已知数字。",
            "formal": "∃ d ∈ {0,…,9} ∀ positions containing '?' substitute with d; d ∉ digits_appearing_in_expression",
            "source_sections": [
              "description"
            ]
          },
          {
            "name": "no_leading_zero_unless_zero",
            "description": "任何数字不能以 '0' 开头,除非该数字本身就是 0（例如 '00' 无效）。",
            "formal": "For each number token (ignoring optional leading '-'), if its length > 1 and first character is '0' then the token must represent the integer 0",
            "source_sections": [
              "description"
            ]
          },
          {
            "name": "number_range_bound",
            "description": "每个数字的取值在 -1000000 到 1000000 之间。",
            "formal": "-1,000,000 ≤ value ≤ 1,000,000",
            "source_sections": [
              "description"
            ]
          },
          {
            "name": "output_selection_minimum",
            "description": "如果有多个数字满足所有约束,选择最小的一个；如果无解,返回 -1。",
            "formal": "answer = min{d | valid(d)} if such d exists else -1",
            "source_sections": [
              "description"
            ]
          }
        ]
      },
      "objective": {
        "type": "minimize_value",
        "description": "find the smallest unknown digit (0-9) that makes the expression true, or -1 if none",
        "target": "digit",
        "requires_solution": false
      },
      "invariant": {
        "invariants": [
          {
            "name": "candidate_digit_ordering",
            "description": "候选数字按升序枚举,首次成功时返回的数字即为满足条件的最小数字。",
            "properties": {
              "direction": "ascending"
            },
            "evidence_source": "both"
          },
          {
            "name": "candidate_digit_exclusion",
            "description": "候选数字集合与原始表达式中已出现的数字不相交,确保未知数字不会与已知数字重复。",
            "properties": {
              "relation": "disjoint"
            },
            "evidence_source": "both"
          }
        ]
      },
      "original_problem": {
        "problem_id": "taco_codewars_24712bdb68a7",
        "title": "546d15cebed2e10334000ed9",
        "description": "To give credit where credit is due: This problem was taken from the ACMICPC-Northwest Regional Programming Contest. Thank you problem writers.\n\nYou are helping an archaeologist decipher some runes. He knows that this ancient society used a Base 10 system, and that they never start a number with a leading zero. He's figured out most of the digits as well as a few operators, but he needs your help to figure out the rest.\n\nThe professor will give you a simple math expression, of the form\n\n```\n[number][op][number]=[number]\n```\n\nHe has converted all of the runes he knows into digits. The only operators he knows are addition (`+`),subtraction(`-`), and multiplication (`*`), so those are the only ones that will appear. Each number will be in the range from -1000000 to 1000000, and will consist of only the digits 0-9, possibly a leading -, and maybe a few ?s. If there are ?s in an expression, they represent a digit rune that the professor doesn't know (never an operator, and never a leading -). All of the ?s in an expression will represent the same digit (0-9), and it won't be one of the other given digits in the expression. No number will begin with a 0 unless the number itself is  0, therefore 00 would not be a valid number. \n\nGiven an expression, figure out the value of the rune represented by the question mark. If more than one digit works, give the lowest one. If no digit works, well, that's bad news for the professor - it means that he's got some of his runes wrong. output -1 in that case.\n\nComplete the method to solve the expression to find the value of the unknown rune. The method takes a string as a paramater repressenting the expression and will return an int value representing the unknown rune or -1 if no such rune exists.\n\n~~~if:php\n**Most of the time, the professor will be able to figure out most of the runes himself, but sometimes, there may be exactly 1 rune present in the expression that the professor cannot figure out (resulting in all question marks where the digits are in the expression) so be careful ;)**\n~~~",
        "input": "",
        "output": "",
        "constraints": "",
        "source": "codewars",
        "standard_solution_code": "import re\n\ndef solve_runes(runes):\n\tfor d in sorted(set('0123456789') - set(runes)):\n\t\ttoTest = runes.replace('?', d)\n\t\tif re.search('([^\\\\d]|\\\\b)0\\\\d+', toTest):\n\t\t\tcontinue\n\t\t(l, r) = toTest.split('=')\n\t\tif eval(l) == eval(r):\n\t\t\treturn int(d)\n\treturn -1"
      }
    }
  },
  "original_problem_references": [
    {
      "problem_id": "taco_codewars_24712bdb68a7",
      "title": "546d15cebed2e10334000ed9",
      "description_summary": "To give credit where credit is due: This problem was taken from the ACMICPC-Northwest Regional Programming Contest. Thank you problem writers. You are helping an archaeologist decipher some runes. He knows that this ancient society used a Base 10 system, and that they never start a number with a leading zero. He's figured out most of the digits as well as a few operators, but he needs your help to figure out the r...",
