          "properties": {
            "locality": "single character replacement, others unchanged"
          }
        },
        {
          "name": "operator_structure_preservation",
          "description": "编辑过程决不变动运算符、等号、负号的位置和数量，因此表达式语法树的结构在整个搜索中保持不变，等式两侧的项数固定。",
          "properties": {
            "invariance": "operator/equal/negation positions constant"
          }
        },
        {
          "name": "digit_disjointness_guarantee",
          "description": "在任何被考虑的候选表达式中，目标数字 d 均不出现在已知数字部分，保证解的唯一标识性。该约束由编辑过滤器在生成状态时主动施加。",
          "properties": {
