      "constraints": [
        {
          "name": "expression_grammar",
          "description": "运算符仅限于 +、-、*；数字序列符合十进制表示，可能带前导负号；? 仅出现在数字内部，不表示运算符或负号；等号左右各有一个有效算术表达式。",
          "formal": "formula matches regex ^[+-]?\\d+([-+*][+-]?\\d+)*=[+-]?\\d+$"
        },
        {
          "name": "target_digit_binding",
          "description": "target_digit d 必须是一个 0-9 的整数，且最终所有 ? 将被替换为 d。d 作为反向目标，是原题解的角色翻转。",
          "formal": "d ∈ {0,…,9} ∧ ∀ occurrences of '?' in formula are substituted by d in the evaluation."
        },
        {
          "name": "edit_operation_contract",
          "description": "允许的编辑操作：选择表达式中一个已知数字字符（即不是 '?'、'-'、运算符、等号）将其替换为另一个数字 '0'-'9'，每次替换计为一次修改。不能增删字符，不能改变字符类型或位置，运算符和负号不可修改。操作保持表达式字符串长度和结构完全不变。",
          "formal": "Op: substitute a character at index i where formula[i] ∈ '0'-'9' and is not a negation sign and is not part of '?' with a digit d' ∈ '0'-'9'. After each op, length(formula) unchanged, and the positions of '=', operators, and '-' (as negation) preserved."
        },
        {
          "name": "modified_expression_constraints",
          "description": "修改后的表达式每个数字必须无前导零（除非该数字本身就是 0）；每个数字的绝对值在 1 到 1,000,000 之间；d 不得出现在最终表达式任何已知数字里（即除 ? 位置外，不能有数字等于 d）。",
          "formal": "For each number token: if len(token) > 1 and token[0]=='0' then token == 0; |value| ≤ 1,000,000; d ∉ set of digits appearing in the modified formula outside of '?' positions."
        },
        {
          "name": "existence_handling",
          "description": "若不存在任何编辑序列能使公式在将 ? 替换为 d 后算术相等且满足所有约束，则答案为 -1；否则答案是最小修改次数。",
          "formal": "if no valid sequence exists, answer = -1; else answer = min |ops| over all valid sequences."
        }
      ]
    },
    "objective": {
      "type": "minimize_edit_count",
      "description": "计算最小的数字替换次数 k，使得可以通过恰好 k 次操作将表达式变形为一个合法表达式，该表达式在把 ? 统一替换为目标数字 d 后算术等式成立且满足所有修改后约束。若 k 存在，额外提供一种具体的修改方案（指明哪些位置改成什么数字）作为存在性证书；如果无法达成，输出 -1。算法必须保证输出的 k 是全局最小值。",
      "target": "minimum number of digit substitutions, plus an executable edit script when k ≥ 0.",
      "requires_solution": true,
      "certificate": "输出具体的替换位置和替换后数字序列，可验证。"
    },
    "invariant": {
      "invariants": [
        {
          "name": "breadth_first_minimality",
          "description": "算法采用宽度优先的顺序探索编辑空间：先检查所有零次修改（原始表达式），若失败则检查所有一次修改产生的表达式，依此类推，首次遇到的满足全部约束且等式成立的表达式对应的修改次数即为最小次数。该性质确保无需探索更深层次即可返回最优。",
