    },
    "applied_helpers": [
      {
        "id": "target_result_binding",
        "selection_reason": "原题结果 d 是使表达式成立的未知数字，直接绑定为新题的反向目标，驱动整个算法围绕如何‘达到该目标’来设计。",
        "affected_axes": [
          "C",
          "O"
        ],
        "schema_changes": [
          "core_constraints: 新增 target_digit_binding 约束，锁定 d 为常量而非待求解变量",
          "objective: 从求解 d 翻转为在给定 d 下求最小修改次数，目标主体由变量变为编辑操作"
