        "value_range": {
          "min": null,
          "max": null
        },
        "properties": {}
      },
      "core_constraints": {
        "constraints": [
          {
            "name": "expression_grammar",
            "description": "运算符仅限于 +、-、*；数字序列符合十进制表示，可能带前导负号；? 仅出现在数字内部，不表示运算符或负号；等号左右各有一个有效算术表达式。",
            "formal": "formula matches regex ^[+-]?\\d+([-+*][+-]?\\d+)*=[+-]?\\d+$"
          },
          {
            "name": "target_digit_binding",
            "description": "target_digit d 必须是一个 0-9 的整数，且最终所有 ? 将被替换为 d。d 作为反向目标，是原题解的角色翻转。",
            "formal": "d ∈ {0,…,9} ∧ ∀ occurrences of '?' in formula are substituted by d in the evaluation."
          },
