{
  "code": "def solve(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    s = lines[0].strip()
    d = int(lines[1].strip())

    # 将所有 ? 替换为 d
    s_replaced = s.replace('?', str(d))

    # 收集所有已知数字字符的位置（原始字符串中的数字）
    known_positions = []
    for i, ch in enumerate(s):
        if ch.isdigit():
            known_positions.append((i, ch))

    # 如果没有任何已知数字，那就无法修改任何东西，但可能等式已成立
    # 此时直接检查 s_replaced 是否成立且满足 d 不出现在已知位置（已知位置没有，所以自动满足）
    if not known_positions:
        left, right = s_replaced.split('=')
        if abs(eval(left)) > 1000000 or abs(eval(right)) > 1000000:
            return '-1'
        try:
            if eval(left) == eval(right):
                # 还需要检查前导零和数值限制
                if check_part(left) and check_part(right):
                    return s_replaced
        except:
            pass
        return '-1'

    # 检查表达式某一部分的数字约束（无等号）
    def check_part(expr):
        i = 0
        n = len(expr)
        while i < n:
            # 一个数字 token 可能以负号开头
            if expr[i].isdigit() or (expr[i] == '-' and i + 1 < n and expr[i + 1].isdigit() and (i == 0 or expr[i - 1] not in '0123456789)')):
                start = i
                if expr[i] == '-':
                    i += 1
                while i < n and expr[i].isdigit():
                    i += 1
                token = expr[start:i]
                num_val = int(token)
                if abs(num_val) > 1000000:
                    return False
                num_part = token[1:] if token[0] == '-' else token
                if len(num_part) > 1 and num_part[0] == '0':
                    return False
            else:
                i += 1
        return True

    # 检查左右两边值是否相等，并满足数字约束
    def check_eq(left, right):
        try:
            if eval(left) != eval(right):
                return False
        except:
            return False
        return check_part(left) and check_part(right)

    # 回溯搜索：为每个已知数字位置分配一个新字符
    n_pos = len(known_positions)
    assigned = [''] * n_pos
    # 预先计算每个位置的可选字符集合，提高一点可读性
    choices_per_pos = []
    for orig_char in [ch for _, ch in known_positions]:
        base_choices = [str(x) for x in range(10) if x != d]
        # 如果原数字不等于 d，可以保留原样
        if orig_char != str(d):
            base_choices.append(orig_char)
        # 去重
        choices_per_pos.append(list(set(base_choices)))

    # 记录找到的第一个可行赋值
    final_assign = None

    def dfs(idx):
        nonlocal final_assign
        if idx == n_pos:
            # 构造修改后的完整字符串
            tmp = list(s_replaced)
            for k, (pos, _) in enumerate(known_positions):
                tmp[pos] = assigned[k]
            new_s = ''.join(tmp)
            if '=' not in new_s:
                return False
            left, right = new_s.split('=', 1)
            if check_eq(left, right):
                final_assign = assigned.copy()
                return True
            return False
        pos, orig_char = known_positions[idx]
        for ch in choices_per_pos[idx]:
            assigned[idx] = ch
            if dfs(idx + 1):
                return True
        return False

    found = dfs(0)
    if not found:
        return '-1'

    # 根据找到的赋值生成最终等式（错误：没有输出修改次数）
    result = list(s_replaced)
    for k, (pos, _) in enumerate(known_positions):
        result[pos] = final_assign[k]
    return ''.join(result)"
}

