import sys
from collections import deque

def solve(input_str: str) -> str:
    lines = input_str.strip().splitlines()
    if len(lines) < 2:
        return "-1"
    formula = lines[0].strip()
    d = int(lines[1].strip())

    # 收集已知数字位置（字符为'0'-'9'的索引）
    known_positions = [i for i, ch in enumerate(formula) if ch.isdigit()]

    # 表达式求值器
    def evaluate(expr: str):
        if not expr:
            return None
        class Parser:
            def __init__(self, s):
                self.s = s
                self.n = len(s)
                self.i = 0
            def parse(self):
                try:
                    val = self.parse_expr()
                    if self.i < self.n:
                        return None
                    return val
                except Exception:
                    return None
            def parse_expr(self):
                left = self.parse_term()
                if left is None:
                    raise ValueError
                while self.i < self.n and self.s[self.i] in '+-':
                    op = self.s[self.i]
                    self.i += 1
                    right = self.parse_term()
                    if right is None:
                        raise ValueError
                    if op == '+':
                        left += right
                    else:
                        left -= right
                return left
            def parse_term(self):
                left = self.parse_factor()
                if left is None:
                    raise ValueError
                while self.i < self.n and self.s[self.i] == '*':
                    self.i += 1
                    right = self.parse_factor()
                    if right is None:
                        raise ValueError
                    left *= right
                return left
            def parse_factor(self):
                sign = 1
                if self.i < self.n and self.s[self.i] == '-':
                    sign = -1
                    self.i += 1
                start = self.i
                while self.i < self.n and self.s[self.i].isdigit():
                    self.i += 1
                if start == self.i:
                    raise ValueError
                num_str = self.s[start:self.i]
                if len(num_str) > 1 and num_str[0] == '0':
                    raise ValueError
                value = int(num_str) * sign
                if abs(value) > 1000000:
                    raise ValueError
                return value
        parser = Parser(expr)
        return parser.parse()

    def check(final_str: str) -> bool:
        if final_str.count('=') != 1:
            return False
        eq_idx = final_str.find('=')
        left = final_str[:eq_idx]
        right = final_str[eq_idx+1:]
        lval = evaluate(left)
        if lval is None:
            return False
        rval = evaluate(right)
        if rval is None:
            return False
        if lval != rval:
            return False
        # 检查 d 不出现在原已知数字位置
        for pos in known_positions:
            if final_str[pos] == str(d):
                return False
        return True

    # BFS
    queue = deque()
    queue.append((formula, 0))
    visited = set()
    visited.add(formula)

    while queue:
        cur_state, steps = queue.popleft()
        # 构造最终等式并检查
        final = ''.join(str(d) if ch == '?' else ch for ch in cur_state)
        if check(final):
            return f"{steps}\n{final}"
        # 生成下一层：修改一个已知数字字符
        for i in known_positions:
            orig_ch = cur_state[i]
            for new_digit in '0123456789':
                if new_digit == orig_ch:
                    continue
                new_chars = list(cur_state)
                new_chars[i] = new_digit
                new_state = ''.join(new_chars)
                if new_state not in visited:
                    visited.add(new_state)
                    queue.append((new_state, steps + 1))
    return "-1"

if __name__ == "__main__":
    inp = sys.stdin.read()
    print(solve(inp))

