def evaluate(s):
    """计算等号左右的值，返回 (left_val, right_val)，若求值失败返回 None"""
    left, right = s.split('=')
    try:
        l_val = eval(left)
        r_val = eval(right)
        return l_val, r_val
    except:
        return None, None

def solve(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    expr = lines[0].strip()
    d = lines[1].strip()

    # 1. 将所有 '?' 替换为 d 得到初始字符串
    s0 = expr.replace('?', d)

    # 2. 找出原始表达式中所有已知数字字符的位置（即不是 '?' 的数字字符）
    known_digit_pos = []
    for i, ch in enumerate(expr):
        if ch.isdigit():
            known_digit_pos.append(i)

    # 3. 如果没有任何已知数字，只能检查替换后的等式是否成立
    if not known_digit_pos:
        l, r = evaluate(s0)
        if l is not None and l == r:
            return f"0\n{s0}"
        else:
            return "-1"

    # 4. 使用迭代加深搜索，尝试最少的修改次数
    # 状态：已知位置上的当前字符列表，初始为原始字符
    init_chars = [expr[i] for i in known_digit_pos]
