    def build_string(chars):
        # 将 s0 转为列表便于修改
        s_list = list(s0)
        for idx, pos in enumerate(known_digit_pos):
            s_list[pos] = chars[idx]
        return ''.join(s_list)

    # 迭代加深
    for changes_limit in range(0, max_changes + 1):
        found = False
        best_solution = None

        def dfs(pos_idx, changes_left, current_chars):
            nonlocal found, best_solution
            if found:
                return
            # 如果剩余位置不够消耗修改次数，剪枝
            if len(known_digit_pos) - pos_idx < changes_left:
                return
            # 如果已经处理完所有已知位置
            if pos_idx == len(known_digit_pos):
                if changes_left == 0:
                    cur_str = build_string(current_chars)
                    lv, rv = evaluate(cur_str)
                    # 错误重点：只检查等式成立，忽略 d 不能出现在已知位置、前导零、绝对值等
                    if lv is not None and lv == rv:
                        found = True
                        best_solution = cur_str
                return

            # 选择不修改当前已知数字
            dfs(pos_idx + 1, changes_left, current_chars)
            if found:
                return
            # 选择修改当前数字（消耗一次修改）
            if changes_left > 0:
                orig_char = current_chars[pos_idx]
                for new_digit in '0123456789':
                    if new_digit == orig_char:
                        continue
                    current_chars[pos_idx] = new_digit
                    dfs(pos_idx + 1, changes_left - 1, current_chars)
                    if found:
                        return
                # 回溯
                current_chars[pos_idx] = orig_char

        dfs(0, changes_limit, init_chars[:])
        if found:
            return f"{changes_limit}\n{best_solution}"

    # 无解
    return "-1"

if __name__ == "__main__":
    raw = sys.stdin.read()
    print(solve(raw))
