    d = int(lines[1].strip())
    n = len(s)

    # 将所有问号替换为数字 d，得到基础串
    base = list(s)
    for i in range(n):
        if base[i] == '?':
            base[i] = str(d)
    base_str = ''.join(base)

    # 收集所有已知数字位置（原始字符就是数字的位置）
    known_pos = []
    org_digits = []
