    # 如果没有任何已知数字，直接检查替换后的等式
    if K == 0:
        if check(base_str):
            return f'0\n{base_str}'
        else:
            return '-1'

    # 尝试修改次数从小到大
    for changes in range(0, K+1):
        if changes == 0:
            if check(base_str):
                return f'0\n{base_str}'
            continue
        # 从 known_pos 中选取 changes 个位置进行修改
        found = False
        best_expr = None
