            prods = [a*c, a*d, b*c, b*d]
            return (min(prods), max(prods), r1[2] and r2[2])

        def eval_range(tokens, assigned):
            values = []
            ops = []
            for tok in tokens:
                if tok[0] == 'NUMBER':
                    rng = token_range(tok, assigned)
                    if rng is None:
                        return None
                    values.append(rng)
                else:
                    op = base[tok[1]:tok[2]]
                    while ops and precedence(ops[-1]) >= precedence(op):
                        if len(values) < 2:
                            return None
                        r2 = values.pop()
                        r1 = values.pop()
                        op_op = ops.pop()
                        if op_op == '+':
                            r = add_range(r1, r2)
                        elif op_op == '-':
                            r = sub_range(r1, r2)
                        elif op_op == '*':
                            r = mul_range(r1, r2)
                        else:
                            return None
                        values.append(r)
                    ops.append(op)
            while ops:
                if len(values) < 2:
                    return None
                r2 = values.pop()
                r1 = values.pop()
                op_op = ops.pop()
                if op_op == '+':
                    r = add_range(r1, r2)
                elif op_op == '-':
                    r = sub_range(r1, r2)
                elif op_op == '*':
                    r = mul_range(r1, r2)
                else:
                    return None
                values.append(r)
            if len(values) != 1:
                return None
            return values[0]

        def range_check(assigned):
            r_left = eval_range(tokens_left, assigned)
            if r_left is None:
                return False
            r_right = eval_range(tokens_right, assigned)
            if r_right is None:
                return False
            if r_left[2] and r_right[2]:
                return r_left[0] == r_right[0]
            return not (r_left[1] < r_right[0] or r_left[0] > r_right[1])

        def dfs(k, max_k, assigned, var_idx):
            if k > max_k:
                return False
            if var_idx == total_vars:
                final = list(base)
                for i in range(len(assigned)):
                    if assigned[i] is not None:
                        final[i] = assigned[i]
                return is_expression_valid(''.join(final))
            if not range_check(assigned):
                return False

            idx, original, can_keep = vars_list[var_idx]
            if can_keep:
                assigned[idx] = original
                if dfs(k, max_k, assigned, var_idx+1):
                    return True
                assigned[idx] = None
            d_str = str(d_val)
            for new_d in range(10):
                if str(new_d) == d_str:
                    continue
                if str(new_d) == original and can_keep:
                    continue
                assigned[idx] = str(new_d)
                if dfs(k+1, max_k, assigned, var_idx+1):
                    return True
                assigned[idx] = None
            return False

        if is_expression_valid(base):
            return 0
        for max_k in range(1, total_vars + 1):
            if dfs(0, max_k, init_assigned.copy(), 0):
                return max_k
        return -1

    min_k = solve(formula, d)

    output_parts = output_string.strip().split('\n')
    if len(output_parts) == 1 and output_parts[0].strip() == '-1':
        return min_k == -1
    if len(output_parts) != 2:
        return False
    try:
        k_out = int(output_parts[0].strip())
        eq_out = output_parts[1].strip()
    except:
        return False

    if min_k == -1:
        return False
    if k_out < min_k:
        return False
    base_str = formula.replace('?', str(d))
    if len(eq_out) != len(base_str):
        return False
    for i, ch in enumerate(formula):
        if ch == '?':
            if eq_out[i] != str(d):
                return False
        elif ch in '+*-*=':
            if eq_out[i] != ch:
                return False
        elif ch.isdigit():
            if eq_out[i] == str(d):
                return False
            if not eq_out[i].isdigit():
                return False
        else:
            return False
    if not is_expression_valid(eq_out):
        return False
    actual_edits = 0
    for i, ch in enumerate(formula):
        if ch.isdigit() and ch != '?':
            if eq_out[i] != ch:
                actual_edits += 1
    if actual_edits != k_out:
        return False
    if k_out != min_k:
        return False
    return True

