import sys

def tokenize(s):
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] == '+' or s[i] == '*':
            tokens.append(s[i])
            i += 1
        elif s[i] == '-':
            # 判断是负号（数字的一部分）还是减号运算符
            if i == 0 or (i > 0 and s[i-1] in '+-*'):  # 负号
                num_str = '-'
                i += 1
                while i < n and (s[i].isdigit() or s[i] == '?'):
                    num_str += s[i]
                    i += 1
                tokens.append(num_str)
            else:  # 减号
                tokens.append('-')
                i += 1
        else:  # 数字或'?'
            num_str = ''
            while i < n and (s[i].isdigit() or s[i] == '?'):
                num_str += s[i]
                i += 1
            tokens.append(num_str)
    return tokens

def check_num_constraints(num_str):
    # 检查前导零和绝对值 <= 1e6
    if num_str.startswith('-'):
        num_part = num_str[1:]
    else:
        num_part = num_str
    if len(num_part) == 0:
        return False
    if len(num_part) > 1 and num_part[0] == '0':
        return False
    val = int(num_str)
    if abs(val) > 1000000:
        return False
    return True

