{"code": "import sys
from collections import deque

def solve(input_str: str) -> str:
    """
    求解最小修改次数，使得修改后的等式在把?替换为d后算术成立。
    注意：这里对表达式的求值采用简单的从左到右顺序，乘号和加减同级。
    """
    lines = input_str.strip().split('\n')
    if len(lines) < 2:
        return "-1"
    formula = lines[0].strip()
    d = int(lines[1].strip())
    original_formula = formula

    base = formula.replace('?', str(d))

    # 原始公式中已知数字的位置（即数字字符，不是问号）
    known_indices = [i for i, ch in enumerate(original_formula) if ch.isdigit()]

    def tokenize(s: str):
        """将等式字符串按数字、运算符、等号进行切分，注意负号可能是数字前缀。"""
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            if s[i].isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(s[i:j])
                i = j
            elif s[i] == '-':
                # 判断是负号还是减号：如果前面是运算符、等号或者开头，则作为负号
                if i == 0 or (s[i-1] in '+-*='):
                    j = i + 1
                    while j < n and s[j].isdigit():
                        j += 1
                    if j == i + 1:   # 孤立的减号（理论上不会出现）
                        tokens.append('-')
                        i += 1
                    else:
                        tokens.append(s[i:j])
                        i = j
                else:
                    tokens.append('-')
                    i += 1
            elif s[i] in '+*=':
                tokens.append(s[i])
                i += 1
            else:
                i += 1   # 跳过可能出现的其他字符
        return tokens

    def wrong_eval(tokens_list):
        """按出现的先后顺序计算表达式值，乘号与加减号优先级相同。"""
        nums = []
        ops = []
        for tok in tokens_list:
            if tok in '+-*':
                ops.append(tok)
            else:
                nums.append(int(tok))
        if not nums:
            return 0
        res = nums[0]
        for i, op in enumerate(ops):
            if i + 1 < len(nums):
                nxt = nums[i + 1]
                if op == '+':
                    res += nxt
                elif op == '-':
                    res -= nxt
                elif op == '*':
                    res *= nxt
        return res

    def is_valid(state_str: str) -> bool:
        """检查修改后的等式字符串是否符合所有约束（数字范围、前导零、d不在已知数字处）。"""
        tokens = tokenize(state_str)
        for token in tokens:
            if token in '+-*=':
                continue
            # 处理数字
            num_str = token
            if num_str[0] == '-':
                digits = num_str[1:]
            else:
                digits = num_str
            # 前导零检查（单独的0或-0是允许的）
            if len(digits) > 1 and digits[0] == '0':
                return False
            # 绝对值检查
            if abs(int(num_str)) > 1000000:
                return False
        # d不能再出现在已知数字位置上
        if any(state_str[i] == str(d) for i in known_indices):
            return False
        return True

    def equality_holds(state_str: str) -> bool:
        """判断等式是否成立（使用从左到右的顺序计算）。"""
        tokens = tokenize(state_str)
        try:
            eq_pos = tokens.index('=')
        except ValueError:
            return False
        left_tokens = tokens[:eq_pos]
        right_tokens = tokens[eq_pos+1:]
        return wrong_eval(left_tokens) == wrong_eval(right_tokens)

    # 初始状态检查
    if is_valid(base) and equality_holds(base):
        return f"0\n{base}"

    # 宽度优先搜索修改
    visited = {base}
    queue = deque()
    queue.append((base, 0))

    while queue:
        state, depth = queue.popleft()
        # 为防止搜索过深，限制修改次数不超过已知数字个数（每个位置最多改一次）
        if depth >= len(known_indices):
            continue
        for idx in known_indices:
            orig_char = state[idx]
            for new_char in map(str, range(10)):
                if new_char == str(d):
                    continue
                if new_char == orig_char:
                    continue
                new_state = state[:idx] + new_char + state[idx+1:]
                if new_state in visited:
                    continue
                if is_valid(new_state):
                    if equality_holds(new_state):
                        return f"{depth+1}\n{new_state}"
                    visited.add(new_state)
                    queue.append((new_state, depth + 1))

    return "-1"
"}

