    known_indices = [i for i, ch in enumerate(original_formula) if ch.isdigit()]

    def tokenize(s: str):
        """将等式字符串按数字、运算符、等号进行切分，注意负号可能是数字前缀。"""
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            if s[i].isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(s[i:j])
                i = j
            elif s[i] == '-':
                # 判断是负号还是减号：如果前面是运算符、等号或者开头，则作为负号
                if i == 0 or (s[i-1] in '+-*='):
                    j = i + 1
                    while j < n and s[j].isdigit():
                        j += 1
                    if j == i + 1:   # 孤立的减号（理论上不会出现）
                        tokens.append('-')
                        i += 1
                    else:
                        tokens.append(s[i:j])
                        i = j
                else:
                    tokens.append('-')
                    i += 1
            elif s[i] in '+*=':
                tokens.append(s[i])
                i += 1
            else:
                i += 1   # 跳过可能出现的其他字符
        return tokens

    def wrong_eval(tokens_list):
        """按出现的先后顺序计算表达式值，乘号与加减号优先级相同。"""
        nums = []
        ops = []
        for tok in tokens_list:
            if tok in '+-*':
                ops.append(tok)
            else:
                nums.append(int(tok))
        if not nums:
            return 0
        res = nums[0]
        for i, op in enumerate(ops):
            if i + 1 < len(nums):
                nxt = nums[i + 1]
                if op == '+':
                    res += nxt
                elif op == '-':
                    res -= nxt
                elif op == '*':
                    res *= nxt
        return res

    def is_valid(state_str: str) -> bool:
        """检查修改后的等式字符串是否符合所有约束（数字范围、前导零、d不在已知数字处）。"""
        tokens = tokenize(state_str)
        for token in tokens:
            if token in '+-*=':
                continue
            # 处理数字
            num_str = token
            if num_str[0] == '-':
                digits = num_str[1:]
            else:
                digits = num_str
            # 前导零检查（单独的0或-0是允许的）
            if len(digits) > 1 and digits[0] == '0':
                return False
            # 绝对值检查
            if abs(int(num_str)) > 1000000:
                return False
        # d不能再出现在已知数字位置上
        if any(state_str[i] == str(d) for i in known_indices):
            return False
        return True

    def equality_holds(state_str: str) -> bool:
        """判断等式是否成立（使用从左到右的顺序计算）。"""
        tokens = tokenize(state_str)
        try:
            eq_pos = tokens.index('=')
        except ValueError:
            return False
        left_tokens = tokens[:eq_pos]
        right_tokens = tokens[eq_pos+1:]
        return wrong_eval(left_tokens) == wrong_eval(right_tokens)

    # 初始状态检查
    if is_valid(base) and equality_holds(base):
        return f"0\n{base}"

    # 宽度优先搜索修改
    visited = {base}
    queue = deque()
    queue.append((base, 0))

    while queue:
        state, depth = queue.popleft()
        # 为防止搜索过深，限制修改次数不超过已知数字个数（每个位置最多改一次）
        if depth >= len(known_indices):
            continue
        for idx in known_indices:
            orig_char = state[idx]
            for new_char in map(str, range(10)):
                if new_char == str(d):
                    continue
                if new_char == orig_char:
                    continue
                new_state = state[:idx] + new_char + state[idx+1:]
                if new_state in visited:
                    continue
                if is_valid(new_state):
                    if equality_holds(new_state):
                        return f"{depth+1}\n{new_state}"
                    visited.add(new_state)
                    queue.append((new_state, depth + 1))

    return "-1"

user_prompt:
# 题目描述信息

title:
公交班次修正

description:
小明是公交公司的调度员，发现某条线路的运行时间记录格式为数学等式，例如“12+34=46”，表示第一段耗时12分钟，第二段耗时34分钟，总耗时46分钟。等式可能包含加号(+)、减号(-)、乘号(*)，且等式两边均可能出现多个数字和运算符。然而部分记录被墨水弄脏，一些数字变得模糊不清，用问号“?”代替。根据其他班次的信息，小明推断所有这些污损数字其实都是同一个数字 d。但即便把“?”都换成 d，等式通常也不成立，这说明记录中还有一些原本清晰的数字其实是错误的。

为此，小明可以修改等式里原本清晰的数字（即那些不是“?”的数字字符）。每次修改只能选择等式中的一个已知数字字符，将其改为另一个数字字符（0-9）。注意：不能增删字符，不能修改运算符（+、-、*）、等号和紧邻数字前的前缀负号。修改后，等式的长度和运算符、等号、前缀负号的位置必须与原式完全一致。

每改动一个数字算作一次修改。小明希望修改次数越少越好。此外，修改完成后，数字 d 不能再出现在等式的任何已知数字位置上——毕竟 d 是当初被弄脏的数字，如果修改后它又出现在了清晰的位置，就自相矛盾了。所有修改后的数字必须满足常规数值约束：不能有前导零（除非该数字本身就是 0），且每个数字的绝对值不超过 1,000,000。

请你帮小明算出最少需要修改几个数字，并给出修改后的完整等式（所有“?”均已替换成 d）。如果无论如何修改都无法满足要求，则直接指出无法做到。

input_format:
输入包含两行。
第一行是一个字符串，表示带有“?”的等式，格式为合法的数学表达式，只包含数字0-9、问号“?”、加号“+”、减号“-”、乘号“*”和等号“=”。其中紧邻数字前的“-”视为该数字的前缀负号，不作为独立的减号运算符；数字前最多有一个前缀负号，且其后紧跟数字或“?”。表达式中可包含多个运算符（例如 a+b*c=d）。
第二行是一个整数 d（0 ≤ d ≤ 9），表示所有“?”代表的数字。

output_format:
如果不存在符合要求的修改方案，输出一行 -1。
否则，第一行输出一个整数 k，表示最少的修改次数；第二行输出一个字符串，表示修改完成且将所有“?”替换为 d 之后的完整等式。该等式可直接作为修改方案的证明。

constraints:
[
  "等式字符串的长度不超过 30。",
  "所有“?”代表同一个数字 d，0 ≤ d ≤ 9。",
  "修改操作：每次只能选择一个已知数字字符（即原始表达式中不是“?”、不是运算符、不是等号、不是前缀负号的数字字符），将其改为另一个数字（0-9）。不能增删字符，不能修改运算符、等号和前缀负号的位置。修改后等式长度与字符的类别位置必须与原式一致。",
  "修改后，等式中的每个数字序列不能有前导零（除非该数字本身就是 0），且每个数字的绝对值不超过 1,000,000。",
  "修改后，数字 d 不得出现在等式中的任何已知数字位置上（即原表达式中原本不是“?”的位置）。",
  "时间限制：2000ms，空间限制：256MB。"
]

