import re
from itertools import combinations, product

def solve(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    formula = lines[0].strip()
    d = int(lines[1].strip())
    d_char = str(d)

    # 识别所有已知数字字符的位置
    known_indices = []
    operators = {'+', '-', '*', '='}
    for i, c in enumerate(formula):
        if c == '?':
            continue
        if c in operators:
            continue
        if c == '-':
            # 是否为前缀负号？
            if i == 0 or formula[i-1] in operators:
                if i+1 < len(formula) and (formula[i+1].isdigit() or formula[i+1] == '?'):
                    continue
        if c.isdigit():
            known_indices.append(i)

    def replace_question_marks(s: str) -> str:
        return s.replace('?', d_char)

    def check(final_str: str) -> bool:
        # 1. d不出现在任何已知数字位置上
        for i in known_indices:
            if final_str[i] == d_char:
                return False
        # 2. 等式成立
        if '=' not in final_str:
            return False
        left, right = final_str.split('=', 1)
        try:
            left_val = eval(left)
            right_val = eval(right)
        except:
            return False
        if left_val != right_val:
            return False
        # 3. 每个数字的绝对值不超过1,000,000（错误：不检查前导零）
        all_numbers = re.findall(r'-?\d+', left) + re.findall(r'-?\d+', right)
        for num_str in all_numbers:
            try:
                val = int(num_str)
            except:
                return False
            if abs(val) > 1000000:
                return False
        return True

    # 检查零次修改
    initial_final = replace_question_marks(formula)
    if check(initial_final):
        return "0\n" + initial_final

    N = len(known_indices)
    for k in range(1, N+1):
        for indices_combo in combinations(known_indices, k):
            orig_chars = [formula[i] for i in indices_combo]
            candidate_lists = []
            for oc in orig_chars:
                candidates = [str(d) for d in range(10) if str(d) != oc]
                candidate_lists.append(candidates)
            for replacements in product(*candidate_lists):
                chars = list(formula)
                for idx, new_c in zip(indices_combo, replacements):
                    chars[idx] = new_c
                temp_formula = ''.join(chars)
                final_str = replace_question_marks(temp_formula)
                if check(final_str):
                    return f"{k}\n{final_str}"
    return "-1"

