    known_positions = []
    q_positions = []
    for idx, ch in enumerate(formula):
        if ch == '?':
            q_positions.append(idx)
        elif ch in '0123456789':
            known_positions.append(idx)

    # 将?替换为d的工具函数
    def replace_q(s):
        return s.replace('?', str(d))

    # 检查表达式是否满足所有约束（已知数字不含d、无前导零、数值范围、等式成立）
    def is_valid(expr):
        # 1. 已知数字位置不能出现d
        for idx in known_positions:
            if expr[idx] == str(d):
                return False

        # 2. 提取所有带符号整数并检查格式
        # 匹配可能的前缀负号 + 数字序列
        import re
        matches = re.finditer(r'-?\d+', expr)
        for m in matches:
            token = m.group()
            # 去除负号
            num_str = token.lstrip('-')
            if num_str[0] == '0' and len(num_str) > 1:
                return False  # 前导零
            try:
                val = int(token)
            except:
                return False
            if abs(val) > 1000000:
                return False

        # 3. 等式成立
        if '=' not in expr:
            return False
        left, right = expr.split('=', 1)
        try:
            # 注意 eval 会处理运算符优先级
            left_val = eval(left)
            right_val = eval(right)
        except:
            return False
        return left_val == right_val

    # 0次修改
    expr0 = replace_q(formula)
    if is_valid(expr0):
        return f'0\n{expr0}'

    # 1次修改：对每个已知数字位置尝试变为0-9（但不能是d，且不与原字符相同）
    for idx in known_positions:
        original = formula[idx]
        for new_digit in '0123456789':
            if new_digit == str(d) or new_digit == original:
                continue
            # 构造新表达式
