def solve(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    formula = lines[0].strip()
    d = int(lines[1].strip())
    query_positions = {i for i, ch in enumerate(formula) if ch == '?'}
    initial_expr = ''.join(str(d) if ch == '?' else ch for ch in formula)
    def get_editable_positions(expr):
        positions = []
        for i, ch in enumerate(expr):
            if ch not in ['?', '+', '*', '=']:
                positions.append(i)
        return positions
    def check_valid(expr, d, query_pos):
        for i, ch in enumerate(expr):
            if i not in query_pos and ch.isdigit() and int(ch) == d:
                return False
        i = 0
        n = len(expr)
        while i < n:
            if expr[i].isdigit() or (expr[i] == '-' and i+1 < n and expr[i+1].isdigit()):
                start = i
                if expr[i] == '-':
                    i += 1
                j = i
                while j < n and expr[j].isdigit():
                    j += 1
                num_str = expr[start:j]
                if len(num_str) > 1 and num_str[0] == '-' and num_str[1] == '0' and num_str != '-0' and len(num_str) > 2:
                    return False
                elif len(num_str) > 1 and num_str[0] == '0':
                    return False
                try:
                    val = int(num_str)
                    if abs(val) > 1000000:
                        return False
                except:
                    return False
                i = j
            else:
                i += 1
        return True
    from collections import deque
    queue = deque()
    queue.append((initial_expr, 0))
    visited = set()
    visited.add(initial_expr)
    while queue:
        expr, edits = queue.popleft()
        left, right = expr.split('=')
        try:
            if eval(left) == eval(right):
                if check_valid(expr, d, query_positions):
                    return f"{edits}\n{expr}"
        except:
            pass
        positions = get_editable_positions(expr)
        for pos in positions:
            orig_ch = expr[pos]
            for new_digit in range(10):
                new_ch = str(new_digit)
                if new_ch != orig_ch:
                    new_expr = expr[:pos] + new_ch + expr[pos+1:]
                    if new_expr not in visited:
                        visited.add(new_expr)
                        queue.append((new_expr, edits + 1))
    return "-1"

