# 当前 checker 完整代码

def check_output(input_string, output_string):
    import sys
    lines = input_string.strip().split('\n')
    if len(lines) != 2:
        return False
    formula = lines[0].strip()
    try:
        d = int(lines[1].strip())
    except:
        return False
    if d < 0 or d > 9:
        return False

    def tokenize(expr):
        tokens = []
        i = 0
        n = len(expr)
        while i < n:
            if expr[i] in '+*-*':
                if expr[i] == '-' and (i == 0 or expr[i-1] in '+*-*'):
                    start = i
                    i += 1
                    while i < n and expr[i].isdigit():
                        i += 1
                    tokens.append(('NUMBER', start, i))
                else:
                    tokens.append(('OP', i, i+1))
                    i += 1
            elif expr[i].isdigit():
                start = i
                while i < n and expr[i].isdigit():
                    i += 1
                tokens.append(('NUMBER', start, i))
            else:
                i += 1
        return tokens

    def precedence(op):
        return 2 if op == '*' else 1

    def check_numbers_valid(expr_str):
        tokens = tokenize(expr_str)
        for tok in tokens:
            if tok[0] == 'NUMBER':
                start, end = tok[1], tok[2]
                token_str = expr_str[start:end]
                if token_str[0] == '-':
                    num_str = token_str[1:]
                else:
                    num_str = token_str
                if len(num_str) > 1 and num_str[0] == '0':
                    return False
                if num_str == '':
                    return False
                try:
                    val = int(token_str)
                except:
                    return False
                if abs(val) > 1000000:
                    return False
        return True

    def evaluate(expr_str):
        tokens = tokenize(expr_str)
        values = []
        ops = []
        for tok in tokens:
            if tok[0] == 'NUMBER':
                val = int(expr_str[tok[1]:tok[2]])
                values.append(val)
            else:
                op = expr_str[tok[1]:tok[2]]
                while ops and precedence(ops[-1]) >= precedence(op):
                    b = values.pop()
                    a = values.pop()
                    op_op = ops.pop()
                    if op_op == '+': values.append(a+b)
                    elif op_op == '-': values.append(a-b)
                    elif op_op == '*': values.append(a*b)
                ops.append(op)
        while ops:
            b = values.pop()
            a = values.pop()
            op_op = ops.pop()
            if op_op == '+': values.append(a+b)
            elif op_op == '-': values.append(a-b)
            elif op_op == '*': values.append(a*b)
        return values[0] if values else 0

    def is_expression_valid(eq_str):
        if '=' not in eq_str:
            return False
        left, right = eq_str.split('=', 1)
        if not check_numbers_valid(left) or not check_numbers_valid(right):
            return False
        try:
            l_val = evaluate(left)
            r_val = evaluate(right)
            return l_val == r_val
        except:
            return False

    def solve(f, d_val):
        base = f.replace('?', str(d_val))
        vars_list = []
        for i, ch in enumerate(f):
            if ch.isdigit() and ch != '?':
                can_keep = (ch != str(d_val))
                vars_list.append((i, ch, can_keep))

        total_vars = len(vars_list)
        left_str, right_str = base.split('=', 1)
        tokens_left = tokenize(left_str)
        tokens_right = tokenize(right_str)

        init_assigned = [None] * len(base)
        for i, ch in enumerate(base):
            if ch in '+*-*=' or f[i] == '?':
                init_assigned[i] = ch

        def token_range(token, assigned):
            ttype, start, end = token
            if ttype != 'NUMBER':
                return None
            s = start
            sign = 1
            if base[s] == '-':
                sign = -1
                s += 1
            e = end
            L = e - s
            min_v = 0
            max_v = 0
            exact = True
            for i in range(L):
                idx = s + i
                ch = assigned[idx]
                if ch is None:
                    if i == 0 and L > 1:
                        low_d = 1
                        high_d = 9
                    else:
                        low_d = 0
                        high_d = 9
                    min_v = min_v * 10 + low_d
                    max_v = max_v * 10 + high_d
                    exact = False
                else:
                    dig = int(ch)
                    if i == 0 and L > 1 and dig == 0:
                        return None
                    min_v = min_v * 10 + dig
                    max_v = max_v * 10 + dig
            if sign == -1:
                min_v, max_v = -max_v, -min_v
            if min_v < -1000000:
                min_v = -1000000
            if max_v > 1000000:
                max_v = 1000000
            if min_v > max_v:
                return None
            return (min_v, max_v, exact)

        def add_range(r1, r2):
            return (r1[0]+r2[0], r1[1]+r2[1], r1[2] and r2[2])
        def sub_range(r1, r2):
            return (r1[0]-r2[1], r1[1]-r2[0], r1[2] and r2[2])
        def mul_range(r1, r2):
            a,b = r1[0], r1[1]
            c,d = r2[0], r2[1]
            prods = [a*c, a*d, b*c, b*d]
            return (min(prods), max(prods), r1[2] and r2[2])

        def eval_range(tokens, assigned):
            values = []
            ops = []
            for tok in tokens:
                if tok[0] == 'NUMBER':
                    rng = token_range(tok, assigned)
                    if rng is None:
                        return None
                    values.append(rng)
                else:
                    op = base[tok[1]:tok[2]]
                    while ops and precedence(ops[-1]) >= precedence(op):
                        if len(values) < 2:
                            return None
                        r2 = values.pop()
                        r1 = values.pop()
                        op_op = ops.pop()
                        if op_op == '+':
                            r = add_range(r1, r2)
                        elif op_op == '-':
                            r = sub_range(r1, r2)
                        elif op_op == '*':
                            r = mul_range(r1, r2)
                        else:
                            return None
                        values.append(r)
                    ops.append(op)
            while ops:
                if len(values) < 2:
                    return None
                r2 = values.pop()
                r1 = values.pop()
                op_op = ops.pop()
                if op_op == '+':
                    r = add_range(r1, r2)
                elif op_op == '-':
                    r = sub_range(r1, r2)
                elif op_op == '*':
                    r = mul_range(r1, r2)
                else:
                    return None
                values.append(r)
            if len(values) != 1:
                return None
            return values[0]

        def range_check(assigned):
            r_left = eval_range(tokens_left, assigned)
            if r_left is None:
                return False
            r_right = eval_range(tokens_right, assigned)
            if r_right is None:
                return False
            if r_left[2] and r_right[2]:
                return r_left[0] == r_right[0]
            return not (r_left[1] < r_right[0] or r_left[0] > r_right[1])

        def dfs(k, max_k, assigned, var_idx):
            if k > max_k:
                return False
            if var_idx == total_vars:
                final = list(base)
                for i in range(len(assigned)):
                    if assigned[i] is not None:
                        final[i] = assigned[i]
                return is_expression_valid(''.join(final))
            if not range_check(assigned):
                return False

            idx, original, can_keep = vars_list[var_idx]
            if can_keep:
                assigned[idx] = original
                if dfs(k, max_k, assigned, var_idx+1):
                    return True
                assigned[idx] = None
            d_str = str(d_val)
