    for i, ch in enumerate(formula):
        if ch == '?':
            if eq_out[i] != str(d):
                return False
        elif ch in '+*-*=':
            if eq_out[i] != ch:
                return False
        elif ch.isdigit():
            if eq_out[i] == str(d):
                return False
            if not eq_out[i].isdigit():
                return False
        else:
            return False
    if not is_expression_valid(eq_out):
        return False
    actual_edits = 0
    for i, ch in enumerate(formula):
        if ch.isdigit() and ch != '?':
            if eq_out[i] != ch:
                actual_edits += 1
    if actual_edits != k_out:
        return False
    if k_out != min_k:
        return False
    return True

