l(left)\n            rv = eval(right)\n            if lv == rv:\n                return True\n        except Exception:\n            pass\n        return False\n\n    def dfs(idx):\n        nonlocal best_cnt, best_expr\n        if idx == len(known_pos):\n            if check_valid():\n                cnt = sum(1 for p in known_pos if mut[p] != base[p])\n                if cnt < best_cnt:\n                    best_cnt = cnt\n                    best_expr = ''.join(mut)\n            return\n        pos = known_pos[idx]\n        orig = base[pos]\n        for cand in range(10):\n            if cand == d:\n                continue\n            mut[pos] = str(cand)\n            dfs(idx+1)\n        mut[pos] = orig\n\n    dfs(0)\n    if best_expr is None:\n        return \"-1\"\n    return f\"{best_cnt}\\n{best_expr}\""
