import sys
from collections import Counter

def solve(input_str: str) -> str:
    data = input_str.strip().split()
    if not data:
        return ""
    n = int(data[0])
    target_gap = int(data[1])
    a = list(map(int, data[2:2+n]))

    # target_gap == 0 的特殊情况
    if target_gap == 0:
        freq = Counter(a)
        max_cnt = max(freq.values())
        return str(n - max_cnt)

    min_ops = n   # 最多移动 n 次
    # 枚举所有保留子集
    for mask in range(1 << n):
        keep = []
        for i in range(n):
            if mask & (1 << i):
                keep.append(a[i])
        k = len(keep)
        if k == n:
            # 全部保留，检查原序列是否直接满足
            sorted_a = sorted(a)
            max_gap = 0
            for i in range(n - 1):
                max_gap = max(max_gap, sorted_a[i+1] - sorted_a[i])
            if max_gap == target_gap:
                min_ops = 0
            continue
        # 部分保留
        unique_vals = sorted(set(keep))
        need = 0
        for i in range(len(unique_vals) - 1):
            gap = unique_vals[i+1] - unique_vals[i]
            if gap > target_gap:
                # 需要插入的最少点数
                need += (gap + target_gap - 1) // target_gap - 1
        if need <= n - k:
            min_ops = min(min_ops, n - k)

    return str(min_ops)

# 本地测试（可删除）
if __name__ == "__main__":
    test_input = "4 3\n1 3 7 9\n"
    print(solve(test_input))  # 期望输出 1

