                dp[i] = max(dp[i], dp[j] + 1)
        max_len = max(max_len, dp[i])
    return str(n - max_len)
"}

raw_response.code:
def solve(input_str: str) -> str:
    data = input_str.strip().split()
    if not data:
        return '0'
    it = iter(data)
    n = int(next(it))
    target_gap = int(next(it))
    nums = [int(next(it)) for _ in range(n)]
    nums.sort()
    # 贪心：寻找最长子序列，使得排序后相邻差不超过 target_gap
    # 认为这样保留的元素越多，操作次数越少
    dp = [1] * n
    max_len = 0 if n == 0 else 1
    for i in range(n):
        for j in range(i):
            if nums[i] - nums[j] <= target_gap:
                dp[i] = max(dp[i], dp[j] + 1)
        max_len = max(max_len, dp[i])
    return str(n - max_len)

