        "difficulty_role": "要求解法处理等价类和有限性证明。",
        "prompt_guidance": [
          "把计数对象直接写进目标定义。",
          "把去重口径写进约束或不变量。"
        ],
        "redlines": [
          "不能只补一个模数。",
          "不能不定义什么算不同答案。"
        ]
      },
      {
        "id": "state_factorization",
        "summary": "把解空间拆成可汇总的计数单元。",
        "must_realize_in": [
          "core_constraints",
          "invariant"
        ],
        "target_axes": [
          "C",
          "V"
        ],
        "innovation_role": "让计数从主状态组织方式中自然长出来。",
        "difficulty_role": "要求解法在分解与汇总层面重建主状态。",
        "prompt_guidance": [
          "让核心约束说明如何拆成计数单元。",
          "让不变量解释单元之间如何避免重复。"
        ],
        "redlines": [
          "不能保持原状态结构不动。",
          "不能把计数只当成结果后处理。"
