        "source": "codeforces",
        "standard_solution_code": "(p, d) = input().split()\np = int(p)\nd = int(d)\nans = p = p + 1\ni = 10\nwhile i <= 1000000000000000000:\n\tif p % i <= d:\n\t\tans = p - p % i\n\ti *= 10\nprint(ans - 1)"
      }
    }
