            "properties": {},
            "evidence_source": "proof"
          }
        ]
      },
      "difficulty": "medium"
    },
    "algorithmic_delta_claim": {
      "seed_solver_core": "扫描 10 的幂 k，确定满足 p % 10^k ≤ d 的最大 k，输出 p - (p % 10^k) - 1。",
